namespace TswapCore;

/// <summary>
/// Generates a platform-appropriate install script for tswap.
/// The script is output to stdout for the user to review before running.
/// </summary>
public static class InstallScript
{
    private const string BinaryPathPlaceholder = "TSWAP_BINARY_PATH_PLACEHOLDER";
    private const string SecureEnclaveDylibStepPlaceholder = "TSWAP_SE_DYLIB_INSTALL_STEP_PLACEHOLDER";

    private static readonly string BashLinuxTemplate = """
        #!/usr/bin/env bash
        # tswap install script — generated by: tswap installscript
        # Review this script, then run: bash installTswap.sh

        set -euo pipefail

        BINARY="TSWAP_BINARY_PATH_PLACEHOLDER"

        # Temporary files of this run, removed however it ends. BROKER_PENDING is set between updating the
        # tswap-broker SELinux module and replacing the broker's labelled copy, which must match.
        CLEANUP=()
        BROKER_PENDING=""
        on_exit() {
          local status=$? p
          for p in "${CLEANUP[@]+"${CLEANUP[@]}"}"; do
            [ -e "$p" ] || continue
            rm -rf "$p" 2>/dev/null || sudo rm -rf "$p" 2>/dev/null || true
          done
          if [ -n "$BROKER_PENDING" ] && [ "$status" -ne 0 ]; then
            echo "!!  Stopped after updating the tswap-broker module but before its labelled copy; they must match. Run this script again." >&2
          fi
        }
        trap on_exit EXIT

        # install_binary SRC DEST [sudo]: copies next to DEST, then renames over it. A running tswap (an unlock
        # agent, a broker) keeps its old file and the new one appears at once; never an in-place overwrite, which
        # on macOS rewrites the pages of a running signed binary.
        install_binary() {
          local src="$1" dest="$2" run="${3:-}" tmp
          $run mkdir -p "$(dirname "$dest")"
          tmp="$($run mktemp "$dest.new.XXXXXX")"
          CLEANUP+=("$tmp")
          $run cp -f "$src" "$tmp"
          $run chmod 0755 "$tmp"
          $run mv -f "$tmp" "$dest"
        }

        echo "==> Installing tswap binary..."

        # User-local install (no sudo required; used for non-sudo commands)
        install_binary "$BINARY" "$HOME/.local/bin/tswap"
        echo "    Installed to ~/.local/bin/tswap"

        # System-wide install (required for 'sudo tswap' commands)
        install_binary "$BINARY" /usr/local/bin/tswap sudo
        echo "    Installed to /usr/local/bin/tswap"
        TSWAP_BROKER_STEP_PLACEHOLDER
        echo "==> Installing tswap skill (SKILL.md)..."
        mkdir -p "$HOME/.agents/skills/tswap"
        "$HOME/.local/bin/tswap" prompt > "$HOME/.agents/skills/tswap/SKILL.md"
        echo "    Written to ~/.agents/skills/tswap/SKILL.md"

        echo "==> Creating Claude Code symlink..."
        mkdir -p "$HOME/.claude/skills"
        [ -e "$HOME/.claude/skills/tswap" ] && ! [ -L "$HOME/.claude/skills/tswap" ] && rm -rf "$HOME/.claude/skills/tswap"
        ln -sfn "$HOME/.agents/skills/tswap" "$HOME/.claude/skills/tswap"
        echo "    Created ~/.claude/skills/tswap -> ~/.agents/skills/tswap"

        echo "==> Installing shell completions..."
        # bash: auto-loaded by bash-completion from the user data dir (no rc edit needed).
        BASH_COMP_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/bash-completion/completions"
        mkdir -p "$BASH_COMP_DIR"
        "$HOME/.local/bin/tswap" completion bash > "$BASH_COMP_DIR/tswap"
        echo "    bash -> $BASH_COMP_DIR/tswap"
        # fish: auto-loaded from the completions dir when fish is installed.
        if command -v fish >/dev/null 2>&1; then
          FISH_COMP_DIR="$HOME/.config/fish/completions"
          mkdir -p "$FISH_COMP_DIR"
          "$HOME/.local/bin/tswap" completion fish > "$FISH_COMP_DIR/tswap.fish"
          echo "    fish -> $FISH_COMP_DIR/tswap.fish"
        fi
        # zsh: write the completion function; the dir must be on fpath (printed below).
        if command -v zsh >/dev/null 2>&1; then
          ZSH_COMP_DIR="$HOME/.zsh/completions"
          mkdir -p "$ZSH_COMP_DIR"
          "$HOME/.local/bin/tswap" completion zsh > "$ZSH_COMP_DIR/_tswap"
          echo "    zsh  -> $ZSH_COMP_DIR/_tswap"
          echo "         (if zsh completion doesn't load, add to ~/.zshrc: fpath+=$ZSH_COMP_DIR; autoload -Uz compinit; compinit)"
        fi
        echo "    Restart your shell to enable completion."

        TSWAP_RUNNING_PLACEHOLDER

        echo ""
        echo "✅ tswap installed successfully."
        echo "   If ~/.local/bin is not on your PATH, add it:"
        echo "   echo 'export PATH=\"\$HOME/.local/bin:\$PATH\"' >> ~/.bashrc"
        """;

    private static readonly string BashMacOSTemplate = """
        #!/usr/bin/env bash
        # tswap install script — generated by: tswap installscript
        # Review this script, then run: bash installTswap.sh

        set -euo pipefail

        TSWAP_MACOS_BINARY_STEPS_PLACEHOLDER

        echo "==> Installing tswap skill (SKILL.md)..."
        mkdir -p "$HOME/.agents/skills/tswap"
        /usr/local/bin/tswap prompt > "$HOME/.agents/skills/tswap/SKILL.md"
        echo "    Written to ~/.agents/skills/tswap/SKILL.md"

        echo "==> Creating Claude Code symlink..."
        mkdir -p "$HOME/.claude/skills"
        [ -e "$HOME/.claude/skills/tswap" ] && ! [ -L "$HOME/.claude/skills/tswap" ] && rm -rf "$HOME/.claude/skills/tswap"
        ln -sfn "$HOME/.agents/skills/tswap" "$HOME/.claude/skills/tswap"
        echo "    Created ~/.claude/skills/tswap -> ~/.agents/skills/tswap"

        echo "==> Installing shell completions..."
        # bash: auto-loaded by bash-completion from the user data dir (no rc edit needed).
        BASH_COMP_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/bash-completion/completions"
        mkdir -p "$BASH_COMP_DIR"
        /usr/local/bin/tswap completion bash > "$BASH_COMP_DIR/tswap"
        echo "    bash -> $BASH_COMP_DIR/tswap"
        # fish: auto-loaded from the completions dir when fish is installed.
        if command -v fish >/dev/null 2>&1; then
          FISH_COMP_DIR="$HOME/.config/fish/completions"
          mkdir -p "$FISH_COMP_DIR"
          /usr/local/bin/tswap completion fish > "$FISH_COMP_DIR/tswap.fish"
          echo "    fish -> $FISH_COMP_DIR/tswap.fish"
        fi
        # zsh: write the completion function; the dir must be on fpath (printed below).
        # macOS ships zsh as the default shell, so this is the common path here.
        if command -v zsh >/dev/null 2>&1; then
          ZSH_COMP_DIR="$HOME/.zsh/completions"
          mkdir -p "$ZSH_COMP_DIR"
          /usr/local/bin/tswap completion zsh > "$ZSH_COMP_DIR/_tswap"
          echo "    zsh  -> $ZSH_COMP_DIR/_tswap"
          echo "         (if zsh completion doesn't load, add to ~/.zshrc: fpath+=$ZSH_COMP_DIR; autoload -Uz compinit; compinit)"
        fi
        echo "    Restart your shell to enable completion."

        TSWAP_RUNNING_PLACEHOLDER

        echo ""
        echo "✅ tswap installed successfully."
        """;

    /// <summary>
    /// The macOS script's binary steps: tswap and the Secure Enclave dylib into /usr/local/bin with sudo. Left out when
    /// installscript runs from that installed copy (the installer package put both there), so the rest of the template,
    /// the per-user steps, is the same text either way.
    /// </summary>
    private static readonly string BashMacOSBinarySteps = """
        BINARY="TSWAP_BINARY_PATH_PLACEHOLDER"

        # Temporary files of this run, removed however it ends. BROKER_PENDING is set between updating the
        # tswap-broker SELinux module and replacing the broker's labelled copy, which must match.
        CLEANUP=()
        BROKER_PENDING=""
        on_exit() {
          local status=$? p
          for p in "${CLEANUP[@]+"${CLEANUP[@]}"}"; do
            [ -e "$p" ] || continue
            rm -rf "$p" 2>/dev/null || sudo rm -rf "$p" 2>/dev/null || true
          done
          if [ -n "$BROKER_PENDING" ] && [ "$status" -ne 0 ]; then
            echo "!!  Stopped after updating the tswap-broker module but before its labelled copy; they must match. Run this script again." >&2
          fi
        }
        trap on_exit EXIT

        # install_binary SRC DEST [sudo]: copies next to DEST, then renames over it. A running tswap (an unlock
        # agent, a broker) keeps its old file and the new one appears at once; never an in-place overwrite, which
        # on macOS rewrites the pages of a running signed binary.
        install_binary() {
          local src="$1" dest="$2" run="${3:-}" tmp
          $run mkdir -p "$(dirname "$dest")"
          tmp="$($run mktemp "$dest.new.XXXXXX")"
          CLEANUP+=("$tmp")
          $run cp -f "$src" "$tmp"
          $run chmod 0755 "$tmp"
          $run mv -f "$tmp" "$dest"
        }

        echo "==> Installing tswap binary..."
        install_binary "$BINARY" /usr/local/bin/tswap sudo
        echo "    Installed to /usr/local/bin/tswap"

        TSWAP_SE_DYLIB_INSTALL_STEP_PLACEHOLDER
        """;

    private const string MacOSBinaryStepsPlaceholder = "TSWAP_MACOS_BINARY_STEPS_PLACEHOLDER";

    private const string MacOSPerUserOnlyStep =
        "echo \"tswap is already installed at /usr/local/bin/tswap; installing the per-user parts only (skill, Claude Code symlink, shell completions)\"";


    private static readonly string PowerShellTemplate = """
        # tswap install script — generated by: tswap installscript
        # Review this script, then run: pwsh installTswap.ps1
        # Requires PowerShell 5.1 or later.

        $ErrorActionPreference = 'Stop'

        $Binary = "TSWAP_BINARY_PATH_PLACEHOLDER"

        # A running unlock agent (tswap agent serve) locks tswap.exe, so the copy below would fail halfway.
        $RunningAgents = @(Get-CimInstance Win32_Process -Filter "Name = 'tswap.exe'" -ErrorAction SilentlyContinue |
            Where-Object { $_.CommandLine -match '\bagent\s+serve\b' })
        if ($RunningAgents.Count -gt 0) {
            Write-Host "A tswap unlock agent is running (pid $($RunningAgents.ProcessId -join ', ')) from the binary this would replace."
            throw "Stop it first: tswap agent stop   (then run this script again, and unlock again afterwards)"
        }

        Write-Host "==> Installing tswap binary..."

        # Install to WindowsApps — this directory is on PATH by default for the current user
        $InstallDir = "$env:USERPROFILE\AppData\Local\Microsoft\WindowsApps"
        New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
        Copy-Item -Force $Binary "$InstallDir\tswap.exe"
        Write-Host "    Installed to $InstallDir\tswap.exe"

        Write-Host "==> Installing tswap skill (SKILL.md)..."
        $SkillDir = "$env:USERPROFILE\.agents\skills\tswap"
        New-Item -ItemType Directory -Force -Path $SkillDir | Out-Null
        [System.IO.File]::WriteAllLines("$SkillDir\SKILL.md", (& "$InstallDir\tswap.exe" prompt))
        Write-Host "    Written to $SkillDir\SKILL.md"

        Write-Host "==> Creating Claude Code symlink..."
        $ClaudeSkillsDir = "$env:USERPROFILE\.claude\skills"
        New-Item -ItemType Directory -Force -Path $ClaudeSkillsDir | Out-Null
        $LinkPath = "$ClaudeSkillsDir\tswap"
        if (Test-Path $LinkPath) {
            Remove-Item -Recurse -Force $LinkPath
        }
        New-Item -ItemType Junction -Path $LinkPath -Target $SkillDir | Out-Null
        Write-Host "    Created $LinkPath -> $SkillDir"

        Write-Host "==> Installing shell completion (PowerShell)..."
        # PowerShell has no completion auto-load dir, so write the script and print the one
        # line to dot-source it from the profile (we don't edit the profile automatically).
        $CompletionFile = "$SkillDir\tswap.completion.ps1"
        [System.IO.File]::WriteAllLines($CompletionFile, (& "$InstallDir\tswap.exe" completion powershell))
        Write-Host "    Written to $CompletionFile"
        Write-Host "    To enable, add this line to your PowerShell profile (path in `$PROFILE):"
        Write-Host "        . `"$CompletionFile`""

        Write-Host ""
        Write-Host "✅ tswap installed successfully."
        """;

    /// <summary>
    /// Generates a bash install script for Linux.
    /// Installs to ~/.local/bin (user) and /usr/local/bin (system/sudo).
    /// </summary>
    public static string GetBashScript(string binaryPath, string? brokerSelinuxModule = null)
        => BashLinuxTemplate
            .Replace(BinaryPathPlaceholder, binaryPath)
            .Replace(BrokerStepPlaceholder, BrokerStep(brokerSelinuxModule))
            .Replace(RunningPlaceholder, RunningReminder(broker: true));

    /// <summary>The broker's SELinux module (<c>contrib/selinux/tswap-broker.cil</c>) embedded in this binary, or null.</summary>
    public static string? BrokerSelinuxModule()
    {
        using var stream = typeof(InstallScript).Assembly.GetManifestResourceStream(BrokerModuleResource);
        if (stream is null)
            return null;
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    private const string BrokerModuleResource = "tswap-broker.cil";
    private const string BrokerStepPlaceholder = "TSWAP_BROKER_STEP_PLACEHOLDER";
    private const string RunningPlaceholder = "TSWAP_RUNNING_PLACEHOLDER";

    /// <summary>
    /// Linux only: a broker set up per docs/BROKER.md runs a labelled copy of the binary,
    /// <c>/usr/local/libexec/tswap-broker</c>, and the <c>tswap-broker</c> SELinux module. Both must follow the
    /// binary (a copy left behind runs the old version; a fresh copy without restorecon is <c>bin_t</c> and runs
    /// unconfined; the module and the binary must match). Each step runs only where that piece is already set up.
    /// The module goes first: it carries the file context restorecon applies to the copy.
    /// </summary>
    private static string BrokerStep(string? module)
    {
        var moduleStep = module is null
            ? ""
            : $"""
               if [ -n "$SEMODULE" ]; then
                 if MODULES="$(sudo "$SEMODULE" -l 2>/dev/null)"; then
                   # grep without -q reads all its input, so pipefail can't see a SIGPIPE from awk.
                   if printf '%s\n' "$MODULES" | awk '{"{print $1}"}' | grep -Ex 'tswap-broker(\.pp)?' >/dev/null; then
                     echo "==> Updating the tswap-broker SELinux module..."
                     CIL_DIR="$(mktemp -d)"
                     CLEANUP+=("$CIL_DIR")
                     # semodule names a module after its file, so the file is tswap-broker.cil.
                     echo "{Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(module))}" | base64 -d > "$CIL_DIR/tswap-broker.cil"
                     if [ -e /usr/local/libexec/tswap-broker ]; then BROKER_PENDING=1; fi
                     sudo "$SEMODULE" -i "$CIL_DIR/tswap-broker.cil"
                     echo "    Installed the tswap-broker module"
                   fi
                 else
                   echo "    Note: couldn't list the SELinux modules (sudo semodule -l failed), so the tswap-broker module was not checked."
                 fi
               fi

               """;
        return """
            # sbin_tool NAME: the path of an admin tool, also where the user's PATH has no /usr/sbin.
            sbin_tool() {
              command -v "$1" 2>/dev/null && return 0
              local d
              for d in /usr/sbin /sbin; do
                if [ -x "$d/$1" ]; then echo "$d/$1"; return 0; fi
              done
              return 1
            }
            SEMODULE="$(sbin_tool semodule || true)"
            RESTORECON="$(sbin_tool restorecon || true)"

            """ + moduleStep + """
            if [ -e /usr/local/libexec/tswap-broker ]; then
              echo "==> Updating the broker's labelled copy..."
              install_binary "$BINARY" /usr/local/libexec/tswap-broker sudo
              if [ -n "$RESTORECON" ]; then
                sudo "$RESTORECON" -v /usr/local/libexec/tswap-broker
              elif [ -n "$SEMODULE" ]; then
                echo "!!  restorecon not found: /usr/local/libexec/tswap-broker is now labelled bin_t, so the broker would run unconfined and containers couldn't connect. As root: restorecon -v /usr/local/libexec/tswap-broker" >&2
              fi
              BROKER_PENDING=""
              echo "    Installed to /usr/local/libexec/tswap-broker"
            fi
            """;
    }

    /// <summary>Names a running agent (and, on Linux, broker): they keep running the old binary. Restarts nothing.</summary>
    private static string RunningReminder(bool broker)
    {
        var brokerCheck = broker
            ? """
              if pgrep -f 'tswap[^ ]* broker serve' >/dev/null 2>&1; then
                echo "    A tswap broker is running and still runs the old version. Restart it as its vault user:"
                echo "      systemctl --user restart tswap-broker"
              fi

              """
            : "";
        return brokerCheck + """
            if pgrep -u "$(id -u)" -f 'tswap[^ ]* agent serve' >/dev/null 2>&1; then
              echo "    A tswap unlock agent is running and still runs the old version until you run:"
              echo "      tswap agent stop     (then unlock again)"
            fi
            """;
    }

    /// <summary>
    /// Generates a bash install script for macOS. Installs to /usr/local/bin (requires sudo).
    /// <paramref name="secureEnclaveDylib"/>, when present, is embedded in the script as a
    /// base64 blob and written out to /usr/local/bin/libtswapse.dylib alongside the binary —
    /// the install step is the deliberate, visible place this happens (not a lazily-extracted
    /// runtime cache the user never asked for and that doesn't depend on the downloaded
    /// binary still existing afterward). Null when this build has no Secure Enclave support
    /// compiled in (non-macOS build of the generator, or the shim didn't build).
    /// </summary>
    /// <param name="binaryInstalled">The running binary is <c>/usr/local/bin/tswap</c> itself (the installer package's
    /// copy, <see cref="InstalledCopy"/>): the script has no binary or dylib step and no <c>sudo</c>, only the per-user
    /// steps, after a line saying so.</param>
    public static string GetMacOSScript(string binaryPath, byte[]? secureEnclaveDylib = null, bool binaryInstalled = false)
    {
        if (binaryInstalled)
            return BashMacOSTemplate
                .Replace(MacOSBinaryStepsPlaceholder, MacOSPerUserOnlyStep)
                .Replace(RunningPlaceholder, RunningReminder(broker: false));
        var dylibStep = secureEnclaveDylib is null
            ? ""
            : $"""
               echo "==> Installing Secure Enclave support library..."
               DYLIB_TMP="$(mktemp)"
               CLEANUP+=("$DYLIB_TMP")
               echo "{Convert.ToBase64String(secureEnclaveDylib)}" | base64 -D > "$DYLIB_TMP"
               install_binary "$DYLIB_TMP" /usr/local/bin/libtswapse.dylib sudo
               echo "    Installed to /usr/local/bin/libtswapse.dylib"
               """;
        return BashMacOSTemplate
            .Replace(MacOSBinaryStepsPlaceholder, BashMacOSBinarySteps)
            .Replace(BinaryPathPlaceholder, binaryPath)
            .Replace(SecureEnclaveDylibStepPlaceholder, dylibStep)
            .Replace(RunningPlaceholder, RunningReminder(broker: false));
    }

    /// <summary>
    /// Generates a PowerShell install script for Windows.
    /// </summary>
    public static string GetPowerShellScript(string binaryPath)
        => PowerShellTemplate.Replace(BinaryPathPlaceholder, binaryPath);

    /// <summary>
    /// Generates the install script appropriate for the current platform.
    /// <paramref name="secureEnclaveDylib"/> is macOS-only — see <see cref="GetMacOSScript"/>.
    /// </summary>
    public static string GetScript(string binaryPath, byte[]? secureEnclaveDylib = null)
    {
        if (OperatingSystem.IsWindows()) return GetPowerShellScript(binaryPath);
        if (OperatingSystem.IsMacOS())  return GetMacOSScript(binaryPath, secureEnclaveDylib);
        return GetBashScript(binaryPath, BrokerSelinuxModule());
    }
}
